#!/bin/zsh
BIN=/home/liskil/QxFx0Rust/target/release/qxfx0
DB=/tmp/opencode/practice/practice.db
rm -f "$DB" "$DB-wal" "$DB-shm"
turn() { "$BIN" --db "$DB" --session-id "$1" turn "$2" >> /tmp/opencode/practice/turns.log 2>&1 || echo "TURN FAILED: $1 $2" >> /tmp/opencode/practice/turns.log; }
S1=( "что такое свобода?" "свобода это возможность выбора" "что такое ответственность?" "ответственность это готовность держать последствия выбора" "но ведь выбор под принуждением не свободен?" "свобода без ответственности это произвол" "я считаю что ответственность первична а свобода вторична" "нет свобода первична: без выбора нечего держать" "свобода требует осознанности" "ответственность требует честности с собой" "осознанный выбор и есть ответственный" "свобода и ответственность две стороны выбора" )
S2=( "что такое память?" "память хранит прошлое" "что такое внимание?" "внимание направляет настоящее" "но память реконструирует а не копирует?" "внимание без памяти слепо" "я утверждаю что память надежнее внимания" "нет внимание точнее: оно видит сейчас" "память это процесс запоминания хранения и воспроизведения" "внимание это выбор что заметить" "прошлое в памяти настоящее во внимании" "память и внимание держат время" )
S3=( "что такое свобода?" "свобода для меня прежде всего выбор" "что такое память?" "память держит кто я" "ты противоречишь себе: выбор без прошлого слеп?" "свобода опирается на память" "я считаю что свобода важнее памяти" "нет без памяти свобода пуста" "выбор помнит" "память выбирает что держать" "свобода и память вместе" "кто я если выбрать нечего?" )
S4=( "что такое истина?" "истина это соответствие реальности" "что такое доверие?" "доверие это ставка на другого" "но доступ к реальности опосредован наблюдателем?" "доверие уязвимо: один провал рушит годы" "я утверждаю что истина важнее доверия" "нет доверие первичнее: без него некому проверять" "истина дисциплина проверки" "доверие решение принять риск" "проверка требует доверия к методу" "истина и доверие держат познание" )
S5=( "что такое внимание?" "внимание это усилие замечать" "что такое ответственность?" "ответственность это ответ за замеченное" "но заметить еще не значит ответить?" "ответственность начинается со внимания" "я считаю внимание важнее ответственности" "нет ответ важнее замечания" "замечать значит уже отвечать" "отвечать значит замечать всерьез" "внимание и ответственность одно движение" "что замечено то и держит" )
i=1; for t in "${S1[@]}"; do turn practice-s$i "$t"; done; i=2; for t in "${S2[@]}"; do turn practice-s$i "$t"; done; i=3; for t in "${S3[@]}"; do turn practice-s$i "$t"; done; i=4; for t in "${S4[@]}"; do turn practice-s$i "$t"; done; i=5; for t in "${S5[@]}"; do turn practice-s$i "$t"; done
echo DONE
